html, body {
  background: var(--appsmith-theme-surfaceColor, #0f172a) !important;
  margin: 0;
  padding: 0;
}

.app {
  height: calc(var(--appsmith-ui-height) * 1px);
  width: calc(var(--appsmith-ui-width) * 1px);
  padding: 8px;
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.ag-theme-alpine {
  --ag-header-background-color: var(--appsmith-theme-surfaceColor, #0f172a);
  --ag-header-foreground-color: var(--appsmith-theme-textStrongColor, #ffffff);
  --ag-odd-row-background-color: var(--appsmith-theme-surfaceColor, #0f172a);
  --ag-background-color: var(--appsmith-theme-cardColor, #1e293b);
  --ag-row-hover-color: var(--appsmith-theme-hoverSoftColor, #1e293b);
  --ag-selected-row-background-color: var(--appsmith-theme-hoverSoftColor, #1e293b);
  --ag-foreground-color: var(--dark-ffffff, var(--appsmith-theme-textColor, #e2e8f0));
  --ag-border-color: var(--appsmith-theme-borderSoftColor, #1e293b);
  --ag-font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --ag-font-size: 14px; --ag-row-height: 44px; --ag-header-height: 48px;
  border-radius: 6px;
  border: 1px solid var(--appsmith-theme-borderSoftColor, #1e293b);
  overflow: hidden;
}

.ag-theme-alpine .ag-row-odd {
  background-color: var(--appsmith-theme-surfaceColor, #0f172a) !important;
}

.ag-theme-alpine .ag-row-even {
  background-color: var(--appsmith-theme-surfaceAltColor, #1e293b) !important;
}

.ag-theme-alpine .ag-row-hover {
  background-color: var(--appsmith-theme-surfaceHoverColor, #26344b) !important;
}

.ag-theme-alpine .ag-cell {
  border-right: 1px solid color-mix(in srgb, var(--appsmith-theme-textStrongColor, #ffffff) 4%, transparent);
  line-height: 44px;
}

.ag-theme-alpine .ag-header {
  font-weight: 600;
  background: var(--appsmith-theme-surfaceColor, #0f172a);
  border-bottom: 2px solid var(--appsmith-theme-borderSoftColor, #1e293b);
}

.ag-theme-alpine .ag-header-cell {
  border-right: 1px solid color-mix(in srgb, var(--appsmith-theme-textStrongColor, #ffffff) 6%, transparent);
}

.ag-theme-alpine .ag-header-cell-text {
  color: var(--appsmith-theme-textStrongColor, #ffffff);
}

.ag-theme-alpine .ag-header-cell-menu-button {
  opacity: 1 !important;
}

.ag-theme-alpine .ag-paging-panel {
  background: var(--appsmith-theme-surfaceColor, #0f172a);
  color: var(--appsmith-theme-textStrongColor, #ffffff);
  border-top: 2px solid var(--appsmith-theme-borderSoftColor, #1e293b);
}

.ag-theme-alpine .ag-paging-panel * {
  color: var(--appsmith-theme-textStrongColor, #ffffff) !important;
}

.ag-theme-alpine .ag-paging-panel .ag-picker-field-wrapper {
  background: var(--dark-1e293b, var(--appsmith-theme-backgroundColor, #1E293A));
  border-color: var(--appsmith-theme-borderSoftColor, #1e293b);
  color: var(--appsmith-theme-textStrongColor, #ffffff);
}

.ag-theme-alpine .ag-paging-button {
  color: var(--appsmith-theme-textStrongColor, #ffffff) !important;
  opacity: 0.85;
}

.ag-theme-alpine .ag-paging-button:hover {
  opacity: 1;
  background: var(--appsmith-theme-hoverSoftColor, #1e293b);
  border-radius: 4px;
}

.ag-theme-alpine .ag-paging-button[disabled] {
  opacity: 0.4;
}

.ag-theme-alpine .ag-paging-button.ag-paging-button-current {
  background: var(--appsmith-theme-textStrongColor, #ffffff);
  color: var(--appsmith-theme-surfaceColor, #0f172a) !important;
  border-radius: 50%;
}

.ag-menu, .ag-menu-option, .ag-tooltip {
  z-index: 999999 !important;
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
  background: var(--appsmith-theme-surfaceColor, #0f172a);
}

::-webkit-scrollbar-track {
  background: var(--appsmith-theme-surfaceColor, #0f172a);
}

::-webkit-scrollbar-thumb {
  background: var(--dark-1e293b, var(--appsmith-theme-backgroundColor, #1E293A));
  border-radius: 4px;
  border: 2px solid var(--appsmith-theme-surfaceColor, #0f172a);
}

::-webkit-scrollbar-thumb:hover {
  background: var(--appsmith-theme-surfaceHoverColor, #26344b);
}

::-webkit-scrollbar-corner {
  background: var(--appsmith-theme-surfaceColor, #0f172a);
}

* {
  scrollbar-color: var(--appsmith-theme-surfaceAltColor, #1e293b) var(--appsmith-theme-surfaceColor, #0f172a);
  scrollbar-width: thin;
}

